// Final business profile: AI detection + fallbacks. Every later step (Google search, Business Profile, report) uses this.
const s = $('Read URL').first().json;
const clues = $('Detection Prompt').first().json;
let r = $input.first().json;
if (typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
const raw = String((((r.choices || [])[0] || {}).message || {}).content || '');
let d = {};
try { d = JSON.parse((raw.match(/\{[\s\S]*\}/) || ['{}'])[0]); } catch (e) { d = {}; }
const ldName = (String(clues.ld || '').match(/"name"\s*:\s*"([^"]{2,80})"/) || [])[1] || '';
const ldCity = (String(clues.ld || '').match(/"addressLocality"\s*:\s*"([^"]{2,60})"/) || [])[1] || '';
const ldRegion = (String(clues.ld || '').match(/"addressRegion"\s*:\s*"([^"]{2,40})"/) || [])[1] || '';
const titleName = String(clues.title || '').split(/\s[|\-–:]\s/).map((x) => x.trim()).filter(Boolean).pop() || '';
const business = String(d.business_name || clues.og_site_name || ldName || titleName || s.business).trim();
const city = String(d.city || ldCity || '').trim();
const region = String(d.region || ldRegion || '').trim();
const keyword = String(d.main_keyword || '').toLowerCase().replace(/\s+/g, ' ').trim();
const isLocal = !!city; // a city on the site = local business (map pack + city in the Google search)
const cityLabel = city ? city + (region ? ', ' + region : '') : '';
const serpKeyword = keyword ? (isLocal ? keyword + ' ' + city : keyword) : business;
return [{ json: Object.assign({}, s, {
  business: business, city: cityLabel, keyword: keyword, serp_keyword: serpKeyword, is_local: isLocal,
  industry: String(d.industry || ''), services: Array.isArray(d.services) ? d.services.slice(0, 6) : [], detect_confidence: d.confidence || (raw ? 'low' : 'none (AI reply failed)')
}) }];

// Picks the homepage + up to 5 important pages from the sitemap (service, about, contact, pricing first) to audit.
const s = $('Settings').first().json;
const txt = (n) => { try { const j = $(n).first().json || {}; return typeof j.data === 'string' ? j.data : ''; } catch (e) { return ''; } };
let xml = txt('Fetch Sitemap');
const locs = (xml.match(/<loc>\s*([^<]+?)\s*<\/loc>/gi) || []).map((l) => l.replace(/<\/?loc>/gi, '').trim());
const pages = locs.filter((u) => !/\.xml(\?|$)/i.test(u) && u.toLowerCase().indexOf(s.domain) !== -1);
const pathOf = (u) => ((u.match(/^https?:\/\/[^\/]+(\/[^?#]*)?/i) || [])[1] || '/');
const weight = (u) => {
  const p = pathOf(u).toLowerCase();
  let w = 10 - p.split('/').filter(Boolean).length * 2;
  if (/(service|pricing|price|plans|about|contact|location|areas?|book|quote|menu|products?)/.test(p)) w += 6;
  if (/(blog|news|tag|category|author|page\/\d|privacy|terms|cookie|login|cart|wp-)/.test(p)) w -= 8;
  return w;
};
const seen = {};
const picked = [s.home];
seen[s.home.replace(/\/+$/, '')] = 1;
pages.sort((a, b) => weight(b) - weight(a)).forEach((u) => {
  const k = u.replace(/\/+$/, '');
  if (picked.length < 6 && !seen[k] && weight(u) > 0) { seen[k] = 1; picked.push(u); }
});
return picked.map((u) => ({ json: { url: u, sitemap_urls: pages.length } }));

// Turns all the raw data (DataForSEO + Google PageSpeed) into scores, findings and a prioritized fix list.
// Then builds the prompt for the AI strategist. No AI here: every number comes from the APIs.
const s = $('Settings').first().json;
const parse = (j) => { let r = j || {}; if (typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} } return r; };
const one = (n) => { try { return parse($(n).first().json); } catch (e) { return {}; } };
const all = (n) => { try { return $(n).all().map((i) => parse(i.json)); } catch (e) { return []; } };
const task = (j) => ((j.tasks || [])[0]) || {};
const res0 = (j) => ((task(j).result || [])[0]) || {};
const txt = (n) => { try { const j = $(n).first().json || {}; return typeof j.data === 'string' ? j.data : ''; } catch (e) { return ''; } };
const r1 = (x) => Math.round(x * 10) / 10;
const issues = []; // { cat, pri: 1 high | 2 medium | 3 low, title, why, fix, where }
const add = (cat, pri, title, why, fix, where) => issues.push({ cat: cat, pri: pri, title: title, why: why, fix: fix, where: where || '' });

// ---------- 1. Pages (DataForSEO On-Page instant pages) ----------
const CHECKS = {
  // bad when TRUE
  no_title: [1, 'Page has no title tag', 'The title is the biggest on-page ranking signal and the blue link people click in Google.', 'Add a unique title (50 to 60 characters) with the main keyword and city near the front.'],
  no_description: [2, 'Missing meta description', 'Google often uses it as the snippet under your link; a good one lifts clicks.', 'Write a 140 to 155 character description with the keyword and a clear reason to click.'],
  no_h1_tag: [1, 'No H1 heading', 'The H1 tells Google and visitors what the page is about.', 'Add exactly one H1 that includes the main keyword for that page.'],
  title_too_long: [3, 'Title is too long', 'Google cuts titles around 60 characters, so the end gets lost.', 'Shorten the title to about 50 to 60 characters, most important words first.'],
  title_too_short: [2, 'Title is too short', 'A short title wastes space you could use for keywords and a reason to click.', 'Expand the title to 50 to 60 characters: service + city + benefit or brand.'],
  duplicate_title_tag: [2, 'More than one title tag', 'Search engines may pick the wrong one.', 'Keep a single title tag in the page head.'],
  duplicate_meta_tags: [3, 'Duplicate meta tags', 'Conflicting meta tags send mixed signals.', 'Remove the duplicates so each meta tag appears once.'],
  irrelevant_title: [2, 'Title does not match the page content', 'Google rewrites or ignores titles that do not match the page.', 'Rewrite the title so it describes what the page actually covers.'],
  irrelevant_description: [3, 'Meta description does not match the content', 'Google will replace it with its own snippet.', 'Rewrite it to summarize the page and include the main keyword.'],
  no_image_alt: [2, 'Images without alt text', 'Alt text helps Google Images, accessibility and context for the page.', 'Add short descriptive alt text to every meaningful image (include the service or city where natural).'],
  no_favicon: [3, 'No favicon', 'Google shows the favicon next to your result on mobile; missing looks unprofessional.', 'Add a square favicon (at least 48x48) and link it in the page head.'],
  high_loading_time: [1, 'Slow page load', 'Slow pages lose visitors and rank lower, especially on phones.', 'Compress images, lazy-load below-the-fold media, cut unused scripts, use caching/CDN.'],
  has_render_blocking_resources: [2, 'Render-blocking scripts or CSS', 'The browser waits for these files before showing anything.', 'Defer or async non-critical JavaScript and inline or preload critical CSS.'],
  large_page_size: [2, 'Page is very large', 'Heavy pages are slow on mobile data.', 'Compress images (WebP/AVIF), remove unused code and fonts.'],
  size_greater_than_3mb: [1, 'Page is over 3 MB', 'Very heavy pages often fail Core Web Vitals.', 'Shrink images and video, remove unused scripts.'],
  low_content_rate: [3, 'Little visible text compared to code', 'Thin pages give Google little to understand or rank.', 'Add useful text: what you offer, who it is for, where, prices or process, FAQs.'],
  low_character_count: [2, 'Very little text on the page', 'Thin content rarely ranks for competitive searches.', 'Expand the page with helpful, specific content (aim for 400+ words on service pages).'],
  low_readability_rate: [3, 'Text is hard to read', 'Hard copy makes visitors leave.', 'Use shorter sentences, plain words and subheadings.'],
  is_redirect: [3, 'URL redirects', 'Linking to redirects wastes crawl budget and slows users.', 'Link straight to the final URL.'],
  is_4xx_code: [1, 'Page returns an error (4xx)', 'Broken pages lose rankings and visitors.', 'Fix or 301-redirect the URL to the right page.'],
  is_5xx_code: [1, 'Server error (5xx)', 'Google drops pages that keep erroring.', 'Check hosting and server logs; fix the error.'],
  is_broken: [1, 'Page is broken', 'Broken pages hurt trust and rankings.', 'Fix the page or redirect it.'],
  broken_links: [1, 'Broken links on the page', 'Broken links frustrate visitors and waste link value.', 'Update or remove every broken link.'],
  broken_resources: [2, 'Broken images, scripts or CSS', 'Missing files break the page and slow it down.', 'Fix the file paths or remove the missing resources.'],
  has_links_to_redirects: [3, 'Links point to redirects', 'Each redirect adds delay.', 'Update links to point to the final URL.'],
  https_to_http_links: [2, 'HTTPS page links to HTTP pages', 'Mixed links look insecure and leak trust.', 'Change every internal link to https://.'],
  no_doctype: [3, 'Missing doctype', 'Browsers may render the page in quirks mode.', 'Add <!DOCTYPE html> at the very top.'],
  no_encoding_meta_tag: [3, 'No character encoding tag', 'Text can display wrong characters.', 'Add <meta charset="utf-8"> in the head.'],
  deprecated_html_tags: [3, 'Old HTML tags in use', 'Outdated code can display badly.', 'Replace deprecated tags with modern HTML/CSS.'],
  has_meta_refresh_redirect: [2, 'Meta refresh redirect', 'Google treats these as weak, slow redirects.', 'Use a server 301 redirect instead.'],
  canonical_to_broken: [1, 'Canonical points to a broken page', 'Google may drop the page from the index.', 'Point the canonical to the correct live URL.'],
  canonical_to_redirect: [2, 'Canonical points to a redirect', 'Confuses Google about the main URL.', 'Set the canonical to the final URL.'],
  recursive_canonical: [2, 'Canonical loop', 'Google cannot tell which URL is the main one.', 'Make each page canonical to itself or one final URL.'],
  redirect_chain: [2, 'Redirect chain', 'Multiple hops slow pages and lose link value.', 'Redirect straight to the final URL in one step.'],
  lorem_ipsum: [1, 'Placeholder lorem ipsum text', 'Looks unfinished to visitors and Google.', 'Replace it with real content.'],
  has_misspelling: [3, 'Spelling mistakes', 'Typos hurt trust.', 'Proofread and fix the misspellings.'],
  flash: [2, 'Uses Flash', 'Flash no longer works in browsers.', 'Replace with HTML5.'],
  frame: [3, 'Uses frames', 'Frames are hard for Google to index.', 'Rebuild without frames.'],
  is_orphan_page: [2, 'Orphan page (no internal links point here)', 'Google finds and values pages through internal links.', 'Link to this page from your menu or related pages.']
};
const GOOD = {
  is_https: [1, 'Site is not on HTTPS', 'Browsers warn visitors and Google uses HTTPS as a ranking signal.', 'Install an SSL certificate and redirect all http:// to https://.'],
  canonical: [2, 'No canonical tag', 'Without it, duplicate URLs can split your ranking power.', 'Add <link rel="canonical"> pointing to the page\'s own preferred URL.'],
  has_html_doctype: [3, 'No HTML5 doctype', 'Browsers may render in quirks mode.', 'Add <!DOCTYPE html>.'],
  seo_friendly_url: [3, 'URL is not SEO friendly', 'Clean, readable URLs help users and Google.', 'Use short, lowercase, hyphenated URLs with the keyword.']
};
const pageRows = [];
const pagesIn = $('Pick Pages To Audit').all().map((i) => i.json.url);
all('DataForSEO: Audit Pages').forEach((j, idx) => {
  const it = (res0(j).items || [])[0];
  const url = (it && it.url) || pagesIn[idx] || '';
  if (!it) { pageRows.push({ url: url, failed: (task(j).status_message || j.message || 'could not crawl') }); return; }
  const m = it.meta || {};
  const c = it.checks || {};
  const pt = it.page_timing || {};
  const content = m.content || {};
  const h1 = ((m.htags || {}).h1) || [];
  const row = {
    url: url, status: it.status_code, score: Math.round(it.onpage_score || 0), title: m.title || '', title_len: m.title_length || 0,
    desc: m.description || '', desc_len: m.description_length || 0, h1: h1, h2_count: (((m.htags || {}).h2) || []).length,
    words: content.plain_text_word_count || 0, readability: content.flesch_kincaid_readability_index ? r1(content.flesch_kincaid_readability_index) : null,
    internal_links: m.internal_links_count || 0, external_links: m.external_links_count || 0, images: m.images_count || 0,
    lcp_ms: pt.largest_contentful_paint || null, load_ms: pt.duration_time || null, size_kb: it.total_transfer_size ? Math.round(it.total_transfer_size / 1024) : null,
    og: !!((m.social_media_tags || {})['og:title']), canonical: m.canonical || '', failed_checks: []
  };
  Object.keys(CHECKS).forEach((k) => { if (c[k] === true) { row.failed_checks.push(k); const d = CHECKS[k]; add('Technical & on-page', d[0], d[1], d[2], d[3], url); } });
  Object.keys(GOOD).forEach((k) => { if (c[k] === false) { row.failed_checks.push('not_' + k); const d = GOOD[k]; add('Technical & on-page', d[0], d[1], d[2], d[3], url); } });
  if (h1.length > 1) add('Technical & on-page', 3, 'More than one H1', 'Several H1s blur the main topic of the page.', 'Keep one H1; turn the others into H2s.', url);
  if (!row.og) add('Technical & on-page', 3, 'No Open Graph tags', 'Links shared on Facebook, LinkedIn and texts show no image or title.', 'Add og:title, og:description and og:image (1200x630).', url);
  if (s.keyword && idx === 0) {
    const kw = s.keyword.toLowerCase(); const sig = kw.split(' ').filter((w) => w.length > 3);
    const has = (t) => { t = String(t || '').toLowerCase(); return t.indexOf(kw) !== -1 || (sig.length && sig.every((w) => t.indexOf(w) !== -1)); };
    if (!has(row.title)) add('Keywords & content', 1, 'Main keyword missing from the homepage title', 'The title is the strongest signal for what the page should rank for.', 'Put "' + s.keyword + '" (or a close variant) near the start of the homepage title.', url);
    if (!h1.some(has)) add('Keywords & content', 2, 'Main keyword missing from the homepage H1', 'The H1 confirms the topic to Google and visitors.', 'Work "' + s.keyword + '" naturally into the H1.', url);
    if (!has(row.desc)) add('Keywords & content', 3, 'Main keyword missing from the meta description', 'Google bolds matching words in the snippet, which lifts clicks.', 'Include the keyword in the meta description.', url);
  }
  if (s.city && idx === 0) {
    const cityW = s.city.toLowerCase().split(',')[0].trim();
    if (cityW && String(row.title + ' ' + h1.join(' ') + ' ' + row.desc).toLowerCase().indexOf(cityW) === -1) add('Local SEO', 1, 'City not mentioned in the homepage title, H1 or description', 'Local rankings depend on Google clearly connecting you to the area you serve.', 'Add "' + s.city.split(',')[0] + '" to the homepage title and H1, and list your service areas on the page.', url);
  }
  if (row.words && row.words < 300) add('Keywords & content', 2, 'Thin page (' + row.words + ' words)', 'Pages with little text rarely rank for anything competitive.', 'Expand to 400 to 800 helpful words: services, process, pricing info, FAQs, proof.', url);
  pageRows.push(row);
});
const okPages = pageRows.filter((p) => !p.failed);
const titles = {}; okPages.forEach((p) => { const t = p.title.toLowerCase(); if (t) titles[t] = (titles[t] || 0) + 1; });
Object.keys(titles).forEach((t) => { if (titles[t] > 1) add('Technical & on-page', 2, 'Duplicate titles across pages', 'Pages with the same title compete with each other in Google.', 'Give every page a unique title that describes that page.', t); });
const descs = {}; okPages.forEach((p) => { const t = p.desc.toLowerCase(); if (t) descs[t] = (descs[t] || 0) + 1; });
if (Object.keys(descs).some((d) => descs[d] > 1)) add('Technical & on-page', 3, 'Duplicate meta descriptions across pages', 'Google ignores repeated descriptions.', 'Write a unique description for each page.', '');
const avgOnpage = okPages.length ? Math.round(okPages.reduce((a, p) => a + p.score, 0) / okPages.length) : null;

// ---------- 2. Robots + sitemap ----------
const robots = txt('Fetch robots.txt');
const sitemap = txt('Fetch Sitemap');
const robotsOk = /user-agent/i.test(robots);
const sitemapOk = /<urlset|<sitemapindex/i.test(sitemap);
const sitemapCount = (sitemap.match(/<loc>/gi) || []).length;
if (!robotsOk) add('Indexing', 2, 'No robots.txt file', 'Robots.txt tells search engines what to crawl and where your sitemap is.', 'Create /robots.txt with "User-agent: *", "Allow: /" and a "Sitemap: ' + s.sitemap_url + '" line.', s.robots_url);
if (robotsOk && /disallow:\s*\/\s*$/im.test(robots) && !/allow:\s*\/\S/i.test(robots)) add('Indexing', 1, 'robots.txt may block the whole site', '"Disallow: /" can stop Google crawling every page.', 'Remove "Disallow: /" unless the site is meant to be hidden.', s.robots_url);
if (robotsOk && !/sitemap:/i.test(robots)) add('Indexing', 3, 'robots.txt does not list your sitemap', 'Listing it helps every search engine find all your pages.', 'Add the line "Sitemap: ' + s.sitemap_url + '" to robots.txt.', s.robots_url);
if (!sitemapOk) add('Indexing', 1, 'No XML sitemap found at /sitemap.xml', 'A sitemap helps Google discover and index all your pages faster.', 'Create a sitemap (most site builders and SEO plugins do it automatically), then submit it in Google Search Console.', s.sitemap_url);
add('Indexing', 2, 'Confirm Google Search Console is set up', 'Search Console shows indexing errors, real search queries and lets you submit your sitemap.', 'Verify the site in Google Search Console, submit the sitemap and check the Pages report for errors.', '');

// ---------- 3. PageSpeed Insights (Google Lighthouse + real-user data) ----------
const psi = (n) => {
  const j = one(n);
  if (j.error || !j.lighthouseResult) return { error: (j.error && j.error.message) || 'no data' };
  const lr = j.lighthouseResult; const cats = lr.categories || {}; const a = lr.audits || {};
  const sc = (k) => (cats[k] && cats[k].score !== null && cats[k].score !== undefined) ? Math.round(cats[k].score * 100) : null;
  const dv = (k) => (a[k] && a[k].displayValue) || '';
  const lab = { fcp: dv('first-contentful-paint'), lcp: dv('largest-contentful-paint'), tbt: dv('total-blocking-time'), cls: dv('cumulative-layout-shift'), si: dv('speed-index') };
  const fm = (j.loadingExperience && j.loadingExperience.metrics) || {};
  const fv = (k) => fm[k] ? { p75: fm[k].percentile, cat: fm[k].category } : null;
  const field = { lcp: fv('LARGEST_CONTENTFUL_PAINT_MS'), inp: fv('INTERACTION_TO_NEXT_PAINT'), cls: fv('CUMULATIVE_LAYOUT_SHIFT_SCORE'), overall: (j.loadingExperience || {}).overall_category || '' };
  const opps = Object.keys(a).map((k) => a[k]).filter((x) => x && x.details && x.details.type === 'opportunity' && (x.details.overallSavingsMs || 0) >= 150)
    .sort((x, y) => (y.details.overallSavingsMs || 0) - (x.details.overallSavingsMs || 0)).slice(0, 8)
    .map((x) => ({ title: x.title, save_ms: Math.round(x.details.overallSavingsMs), save_kb: x.details.overallSavingsBytes ? Math.round(x.details.overallSavingsBytes / 1024) : null }));
  const failing = (cat) => ((cats[cat] || {}).auditRefs || []).map((r) => a[r.id]).filter((x) => x && x.score !== null && x.score < 0.9 && ['notApplicable', 'manual', 'informative'].indexOf(x.scoreDisplayMode) === -1).map((x) => x.title).slice(0, 12);
  return { perf: sc('performance'), seo: sc('seo'), a11y: sc('accessibility'), bp: sc('best-practices'), lab: lab, field: field, opps: opps, fail_seo: failing('seo'), fail_a11y: failing('accessibility'), fail_bp: failing('best-practices') };
};
const mob = psi('PageSpeed: Mobile');
const desk = psi('PageSpeed: Desktop');
if (!mob.error) {
  if (mob.perf !== null && mob.perf < 50) add('Speed & Core Web Vitals', 1, 'Mobile speed score is poor (' + mob.perf + '/100)', 'Most local searches happen on phones; slow mobile pages lose rankings and calls.', 'Work through the speed fixes below, starting with the biggest savings.', s.home);
  else if (mob.perf !== null && mob.perf < 90) add('Speed & Core Web Vitals', 2, 'Mobile speed score needs work (' + mob.perf + '/100)', 'Faster pages keep more visitors and help Core Web Vitals.', 'Apply the top speed fixes below.', s.home);
  if (mob.field.lcp && mob.field.lcp.cat && mob.field.lcp.cat !== 'FAST') add('Speed & Core Web Vitals', 1, 'Real visitors see a slow main image/text (LCP ' + r1(mob.field.lcp.p75 / 1000) + 's)', 'Largest Contentful Paint is a Core Web Vital Google uses for ranking; good is under 2.5s.', 'Compress and preload the hero image, use a CDN, cut render-blocking code.', s.home);
  if (mob.field.inp && mob.field.inp.cat && mob.field.inp.cat !== 'FAST') add('Speed & Core Web Vitals', 2, 'Page reacts slowly to taps (INP ' + mob.field.inp.p75 + 'ms)', 'Interaction to Next Paint is a Core Web Vital; good is under 200ms.', 'Reduce heavy JavaScript, chat widgets and third-party scripts.', s.home);
  if (mob.field.cls && mob.field.cls.cat && mob.field.cls.cat !== 'FAST') add('Speed & Core Web Vitals', 2, 'Layout jumps while loading (CLS ' + r1(mob.field.cls.p75 / 100) + ')', 'Cumulative Layout Shift is a Core Web Vital; good is under 0.1.', 'Set width/height on images and embeds, reserve space for banners.', s.home);
  mob.opps.slice(0, 5).forEach((o) => add('Speed & Core Web Vitals', o.save_ms > 1000 ? 1 : 2, 'Speed fix: ' + o.title, 'Google estimates this saves about ' + r1(o.save_ms / 1000) + 's on mobile' + (o.save_kb ? ' (' + o.save_kb + ' KB)' : '') + '.', 'Ask your developer or site builder support to apply: "' + o.title + '".', s.home));
  mob.fail_seo.forEach((t) => add('Technical & on-page', 2, 'Google Lighthouse SEO check failed: ' + t, 'Lighthouse flags basic SEO problems Google can see.', 'Fix: ' + t + '.', s.home));
  mob.fail_a11y.slice(0, 6).forEach((t) => add('Accessibility & trust', 3, 'Accessibility: ' + t, 'Accessible sites are easier for everyone to use and reduce legal risk.', 'Fix: ' + t + '.', s.home));
  mob.fail_bp.slice(0, 4).forEach((t) => add('Accessibility & trust', 3, 'Best practice: ' + t, 'Lighthouse best-practice failures can signal security or quality issues.', 'Fix: ' + t + '.', s.home));
}

// ---------- 4. Visibility (DataForSEO Labs) ----------
const ov = ((res0(one('DataForSEO: Domain Overview')).items || [])[0] || {}).metrics || {};
const org = ov.organic || {};
const rankedItems = (res0(one('DataForSEO: Ranked Keywords')).items || []).map((it) => ({
  kw: ((it.keyword_data || {}).keyword) || '', vol: (((it.keyword_data || {}).keyword_info) || {}).search_volume || 0,
  pos: (((it.ranked_serp_element || {}).serp_item) || {}).rank_group || null, url: (((it.ranked_serp_element || {}).serp_item) || {}).relative_url || (((it.ranked_serp_element || {}).serp_item) || {}).url || ''
})).filter((k) => k.kw);
const top3 = rankedItems.filter((k) => k.pos && k.pos <= 3).length;
const top10 = rankedItems.filter((k) => k.pos && k.pos <= 10).length;
const striking = rankedItems.filter((k) => k.pos && k.pos > 10 && k.pos <= 30).sort((a, b) => b.vol - a.vol).slice(0, 15);
const vis = { keywords: org.count || rankedItems.length, top3: (org.pos_1 || 0) + (org.pos_2_3 || 0) || top3, top10: ((org.pos_1 || 0) + (org.pos_2_3 || 0) + (org.pos_4_10 || 0)) || top10, etv: org.etv ? Math.round(org.etv) : 0, traffic_value: org.estimated_paid_traffic_cost ? Math.round(org.estimated_paid_traffic_cost) : 0 };
if (!vis.keywords) add('Keywords & content', 1, 'Google shows almost no rankings for this site yet', 'If you do not rank for any searches, customers cannot find you on Google.', 'Build one strong page per service and per main city, then add helpful blog posts targeting real customer questions.', '');
else if (vis.top10 < 10) add('Keywords & content', 2, 'Only ' + vis.top10 + ' keywords on page 1 of Google', 'Page 1 gets almost all the clicks.', 'Improve the pages ranking 11 to 30 (list below) first: they are the fastest wins.', '');
if (striking.length) add('Keywords & content', 1, striking.length + ' keywords are close to page 1 (positions 11 to 30)', 'Small improvements to these pages can move them onto page 1 quickly.', 'For each, expand the ranking page, add the exact phrase in a heading, add FAQs and internal links. See "Striking distance keywords".', '');

// ---------- 5. Competitors ----------
const giant = /(youtube|facebook|instagram|linkedin|yelp|reddit|wikipedia|amazon|pinterest|tiktok|twitter|x\.com|quora|google|apple|bbb\.org|angi|homeadvisor|thumbtack|indeed|nextdoor|tripadvisor|yellowpages|mapquest)/i;
