// kie.ai sometimes repeats chunks of a long reply ("If youARTICLE=== ... If you run").
// This removes any chunk (40+ chars) that exactly repeats the text right before it, then passes the reply on.
const fix = (t) => {
  let out = '';
  let i = 0;
  const n = t.length;
  while (i < n) {
    let skip = 0;
    const maxL = Math.min(600, out.length, n - i);
    for (let L = maxL; L >= 40; L--) {
      if (t.charCodeAt(i) !== out.charCodeAt(out.length - L)) continue;
      if (t.substr(i, L) === out.slice(-L)) { skip = L; break; }
    }
    if (skip) i += skip; else { out += t[i]; i++; }
  }
  return out;
};
